typeDefs:
interface DiscordMessage {
    id: string;
    text: string;
    channelId: string;
    guildId?: string;
    timestamp: string;
}

interface DiscordClient {
    // ─── 发送与交互 ───

    /**
     * 发送文本消息到指定频道。
     * @param channelId 目标频道 ID（由 sandbox 上下文自动填入当前频道）
     * @param text 消息内容
     * @param opts 可选参数
     * @example sendText(channelId, "你好！")
     * @example sendText(channelId, "回复你的问题", { replyTo: "1234567890" })
     */
    sendText(channelId: string, text: string, opts?: { replyTo?: string }): Promise<DiscordMessage>;

    /**
     * 发送媒体消息（附件）到指定频道。
     * @param channelId 目标频道 ID
     * @param media 媒体对象，支持 URL 或文件内容
     * @param opts 可选参数
     * @example sendMedia(channelId, { url: "https://example.com/image.png", caption: "看看这张图" })
     */
    sendMedia(channelId: string, media: { url?: string; file?: string; caption?: string; fileName?: string }, opts?: { replyTo?: string }): Promise<DiscordMessage>;

    // ─── 状态操作 ───

    /**
     * 在频道中显示 "正在输入..." 状态。
     * @param channelId 目标频道 ID
     */
    sendTyping(channelId: string): Promise<void>;
}

interface TopicNode {
    id: string;
    chatId: string;
    label: string;
    summary: string;
    keyPoints: string[];
    participants: string[];
    messageRange: { messageIds: string[]; count: number };
    startedAt: string;
    endedAt: string | null;
    sentiment: 'positive' | 'neutral' | 'negative' | 'mixed';
    keywords: string[];
    createdAt: string;
    updatedAt: string;
}

interface CoreFact {
    id: string;
    subject: string;
    content: string;
    category: FactCategory;
    confidence: number;
    createdAt: string;
    expiresAt: string | null;
}

interface PersonIdentity {
    userId: string;
    displayName: string;
    aliases: string[];
    totalMessageCount: number;
    lastSeenAt: string;
    firstSeenAt: string;
}

interface PersonGroupProfile {
    userId: string;
    chatId: string;
    dunbarTier: 1 | 2 | 3 | 4;
    traits: string[];
    interests: string[];
    communicationStyle: string;
    relationToAgent: string;
    messageCount: number;
    lastSeenAt: string;
}

interface RecallOptions {
    chatId?: string;
    userId?: string;
    daysBack?: number;
    maxResults?: number;
    categories?: FactCategory[];
    deepRecallThreshold?: number;
}

interface RecallResult {
    topics: TopicNode[];
    facts: Array<{
        content: string;
        category: FactCategory;
        subject: string;
        confidence: number;
    }>;
    persons: PersonGroupProfile[];
    deepSummary?: string;
}

interface HistoryBrowseRequest {
    /** 自然语言搜索意图 */
    intent: string;
    hints?: {
        chatId?: string;
        userId?: string;
        topicLabel?: string;
        topicId?: string;
        hoursBack?: number;
        daysBack?: number;
    };
    contextWindow?: number;
    maxSegments?: number;
}

interface HistoryBrowseResult {
    answer: string;
    segments: Array<{
        topicLabel: string;
        timeRange: { from: string; to: string };
        messages: Array<{
            messageId: string;
            userId: string;
            displayName: string;
            text: string;
            timestamp: string;
        }>;
        relevanceScore: number;
    }>;
    messagesRead: number;
}

interface MemoryStore {
    /**
     * 统一记忆检索入口
     * 使用向量搜索 + 关键词搜索混合检索
     * @example
     * const result = await memory.recall("alice 东京", {
     *   chatId: "-100xxx",
     *   userId: "alice_123",
     *   categories: ['preference', 'plan'],
     * });
     */
    recall(query: string, options?: RecallOptions): Promise<RecallResult>;

    /**
     * 消息档案检索
     * 话题索引引导 + 模糊搜索 + cheap model 深度阅读
     * @example
     * const result = await memory.browseHistory({
     *   intent: "谁说过要去京都吃抹茶",
     *   hints: { chatId: "-100xxx", daysBack: 7 },
     * });
     */
    browseHistory(request: HistoryBrowseRequest): Promise<HistoryBrowseResult>;

    /**
     * 对指定群组进行反思总结
     * 读取上次反思以来的 topics 和 interactions，生成结构化总结
     */
    reflect(chatId: string): Promise<{
        reflectedPeriod: { from: string; to: string };
        topicsSummary: Array<{ label: string; summary: string; participants: string[]; sentiment: string }>;
        personUpdates: Array<{ userId: string; chatId: string; changes: string }>;
        groupUpdates: string;
        newCoreFacts: string[];
        mergedEpisodes: number;
        insights: string;
    }>;
}

type FactCategory =
    | 'biographical'
    | 'preference'
    | 'anecdote'
    | 'opinion'
    | 'plan'
    | 'relationship'
    | 'general';

interface Peer {
    id: number;
    displayName?: string;
    title?: string;
    username?: string;
}

interface User extends Peer {
    firstName: string;
    lastName?: string;
    isBot: boolean;
}

interface Chat {
    id: number;
    title?: string;
    username?: string;
    type: "private" | "group" | "supergroup" | "channel";
}

interface Message {
    id: number;
    text: string;
    date: Date;
    chat: Chat;
    sender: Peer;
    isMention: boolean;
    replyToMessage?: any;
    media?: unknown;
}

interface Dialog {
    peer: Peer;
    lastMessage?: Message;
    unreadCount: number;
}

interface Emitter<T> {
    add(handler: (event: T) => void | Promise<void>): void;
    remove(handler: (event: T) => void | Promise<void>): void;
    once(handler: (event: T) => void | Promise<void>): void;
    clear(): void;
}

interface TelegramClient {
    // ─── 发送与交互 ───
    sendText(chatId: number | string, text: string, opts?: { replyTo?: number }): Promise<Message>;
    /**
     * 发送媒体消息。支持 URL 和本地文件路径。
     * @example sendMedia(chatId, { type: 'photo', file: 'https://example.com/img.jpg', caption: '看看这个' })
     * @example sendMedia(chatId, { type: 'photo', file: '/path/to/local/image.jpg' })
     */
    sendMedia(chatId: number | string, media: string | { type: 'photo' | 'video' | 'document' | 'audio' | 'auto'; file: string; caption?: string; fileName?: string }, opts?: { replyTo?: number }): Promise<Message>;
    /** 发送磁盘文件到聊天（通过绝对路径）。host 侧读取文件并上传。始终作为文件/文档发送。 */
    sendFile(chatId: number | string, filePath: string, opts?: { replyTo?: number; caption?: string; fileName?: string; mimeType?: string }): Promise<Message>;
    /**
     * 发送贴纸。通过 uniqueFileId 引用本地已缓存的贴纸文件。
     * @example sendSticker(chatId, 'AgADAgATxxxxxx')
     */
    sendSticker(chatId: number | string, uniqueFileId: string, opts?: { replyTo?: number }): Promise<Message>;

    // ─── 信息获取 ───
    getMe(): Promise<User>;
    getChat(chatId: number | string): Promise<Chat>;
    getUser(userId: number | string): Promise<User>;
    /** 获取最近的对话列表（包含 peer、最后一条消息、未读数） */
    getDialogs(opts?: { limit?: number }): Promise<Dialog[]>;
    // [USERBOT_ONLY_BEGIN]
    getChatMembers(chatId: number | string, opts?: { limit?: number }): Promise<Peer[]>;
    getHistory(chatId: number | string, opts?: { limit?: number }): Promise<Message[]>;

    // ─── 迭代器 (for await) ───
    iterHistory(chatId: number | string, opts?: { limit?: number }): AsyncIterable<Message>;
    iterDialogs(opts?: { limit?: number }): AsyncIterable<Dialog>;

    // ─── 群组管理 ───
    /** 加入一个群聊或频道 */
    joinChat(chatId: number | string): Promise<void>;
    /** 退出一个群聊或频道 */
    leaveChat(chatId: number | string): Promise<void>;

    // ─── 状态操作 ───
    readHistory(chatId: number | string): Promise<void>;
    // [USERBOT_ONLY_END]
    sendTyping(chatId: number | string): Promise<void>;
}
